480      private static boolean definedBelow(MethodClosure m, Set<SingleFcn> provided) {
481          List<List<FType>> covers = new ArrayList<List<FType>>();
482          List<FType> dm = null;
483          for (SingleFcn sf : provided) {
484              if (sf == m || !(sf instanceof MethodClosure)) continue;
485              MethodClosure k = (MethodClosure) sf;
486              if (!hasBody(k) || k.selfParameterIndex != m.selfParameterIndex ||
487                  !k.asMethodName().equals(m.asMethodName())) continue;
488              try {
489                  List<FType> dk = k.getDomain();
490                  dm = m.getDomain();
491                  if (dk.size() != dm.size()) continue;
492                  boolean below = true;
493                  boolean equal = true;
494                  for (int i = 0; below && i < dk.size(); i++) {
495                      below = dk.get(i).subtypeOf(dm.get(i));
496                      equal = equal && below && dm.get(i).subtypeOf(dk.get(i));
497                  }
498                  if (!below) continue;
499                  if (equal) return true;
500                  covers.add(dk);
501              }
502              catch (FortressException ex) {
503                  continue;
504              }
505          }
506          if (covers.isEmpty()) return false;
507          int n = dm.size();
508          int[] steps = {OverloadedFunction.OVERLAP_STEPS};
509          List<List<Set<FType>>> parts = new ArrayList<List<Set<FType>>>(n);
510          long combinations = 1;
511          for (int i = 0; i < n; i++) {
512              List<FType> at = new ArrayList<FType>(covers.size());
513              for (List<FType> c : covers) at.add(c.get(i));
514              List<Set<FType>> pi = coverParts(dm.get(i), at, new HashSet<FType>(), steps);
515              if (pi == null) return false;
516              parts.add(pi);
517              combinations *= pi.size();
518              if (combinations > OverloadedFunction.OVERLAP_PARTS) return false;
519          }
520          int[] index = new int[n];
521          while (true) {
522              boolean covered = false;
523              for (List<FType> c : covers) {
524                  boolean inside = true;
525                  for (int i = 0; inside && i < n; i++) {
526                      inside = OverloadedFunction.someBelow(parts.get(i).get(index[i]), c.get(i));
527                  }
528                  if (inside) {
529                      covered = true;
530                      break;
531                  }
532              }
533              if (!covered) return false;
534              int i = 0;
535              while (i < n && ++index[i] == parts.get(i).size()) {
536                  index[i] = 0;
537                  i++;
538              }
539              if (i == n) return true;
540          }
541      }

